     5	public class ClaimOffice {
     6	
     7	    private static final int PROCESSING_FEE_IN_G = 5;
     8	
     9	    private final PolicyWideModifiers policyWideModifiers;
    10	
    11	    public ClaimOffice(Customer customer) {
    12	        this.policyWideModifiers = new PolicyWideModifiers(customer);
    13	    }
    14	
    15	    /**
    16	     * The policy base premium is the sum of the base premiums of the main items
    17	     * and of the components, each priced by its own MHPCO pricing policy.
    18	     */
    19	    public int basePremium(List<Item> items) {
    20	        return MainItemPricing.mainItemsBasePremium(items)
    21	                + ComponentPricing.componentsBasePremium(items);
    22	    }
    23	
    24	    /**
    25	     * Item-specific modifiers apply to the base premium of the affected item,
    26	     * not to the policy total.
    27	     */
    28	    public BigDecimal premiumAfterItemModifiers(List<Item> items) {
    29	        return BigDecimal.valueOf(basePremium(items))
    30	                .add(ItemRiskSurcharges.totalItemSurcharges(items));
    31	    }
    32	
    33	    /**
    34	     * The MHPCO assembles a premium in a fixed order: the policy base premium,
    35	     * then the item-specific risk surcharges, then the policy-wide modifiers,
    36	     * and the processing fee at the very end.
    37	     */
    38	    public int quote(List<Item> items) {
    39	        BigDecimal premium = premiumAfterItemModifiers(items);
    40	        BigDecimal quotedPremium = premium
    41	                .add(policyWideModifiers.totalPolicyModifiers(premium))
    42	                .add(BigDecimal.valueOf(PROCESSING_FEE_IN_G));
    43	        policyWideModifiers.recordContractIssued();
    44	        return roundedInTheMhpcoFavour(quotedPremium);
    45	    }
    46	
    47	    /**
    48	     * All amounts are rounded to whole G in the MHPCO's favour: a premium the
    49	     * customer owes is rounded up.
    50	     */
    51	    private static int roundedInTheMhpcoFavour(BigDecimal premium) {
    52	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    53	    }
    54	}
