     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * A percentage of an amount in G, as the MHPCO measures every premium
     5	 * modifier: a risk surcharge against an item's base premium, a discount or
     6	 * assessment surcharge against the policy premium.
     7	 *
     8	 * This is the one place that says how the MHPCO turns a modifier percentage
     9	 * into an amount, so a change to that arithmetic is made here and nowhere
    10	 * else. The amount is kept as a fraction: only the final premium or payout is
    11	 * rounded.
    12	 */
    13	public final class Percentage {
    14	
    15	    private static final BigDecimal WHOLE = BigDecimal.valueOf(100);
    16	
    17	    private Percentage() {
    18	    }
    19	
    20	    public static BigDecimal of(BigDecimal amountInG, int percent) {
    21	        return amountInG.multiply(BigDecimal.valueOf(percent)).divide(WHOLE);
    22	    }
    23	
    24	    public static BigDecimal of(int amountInG, int percent) {
    25	        return of(BigDecimal.valueOf(amountInG), percent);
    26	    }
    27	}
